#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <algorithm>

int main() {
    std::string lineA, lineB;
    std::getline(std::cin, lineA);
    std::getline(std::cin, lineB);

    // Replace all underscores with spaces and trim
    for (auto &ch : lineB) {
        if (ch == '_') ch = ' ';
    }
    // Trim leading and trailing spaces
    size_t start = lineB.find_first_not_of(' ');
    size_t end = lineB.find_last_not_of(' ');
    std::string temp = (start == std::string::npos) ? "" : lineB.substr(start, end - start + 1);

    // Extract content inside parentheses
    std::string insideContent;
    int insideFlag = 0;
    for (char c : temp) {
        if (c == '(') {
            insideFlag = 1;
        } else if (c == ')') {
            insideContent += ' ';
            insideFlag = 0;
        } else if (insideFlag == 1) {
            insideContent += c;
        }
    }

    // Remove all parentheses and their content from lineB
    std::string s = lineB;
    size_t pos;
    while ((pos = s.find('(')) != std::string::npos) {
        size_t closePos = s.find(')', pos);
        if (closePos == std::string::npos) break;
        s = s.substr(0, pos) + " " + s.substr(closePos + 1);
    }

    // Replace multiple spaces with single space and trim
    std::string temp_s;
    bool in_space = false;
    for (char c : s) {
        if (c == ' ') {
            if (!in_space) {
                temp_s += c;
                in_space = true;
            }
        } else {
            temp_s += c;
            in_space = false;
        }
    }
    // Trim leading and trailing spaces
    size_t start_s = temp_s.find_first_not_of(' ');
    size_t end_s = temp_s.find_last_not_of(' ');
    s = (start_s == std::string::npos) ? "" : temp_s.substr(start_s, end_s - start_s + 1);

    // Process insideContent
    std::string insideStr = insideContent;
    // Replace multiple spaces with single space and trim
    std::string temp_in;
    in_space = false;
    for (char c : insideStr) {
        if (c == ' ') {
            if (!in_space) {
                temp_in += c;
                in_space = true;
            }
        } else {
            temp_in += c;
            in_space = false;
        }
    }
    size_t start_in = temp_in.find_first_not_of(' ');
    size_t end_in = temp_in.find_last_not_of(' ');
    insideStr = (start_in == std::string::npos) ? "" : temp_in.substr(start_in, end_in - start_in + 1);

    // Split s into words
    std::istringstream iss(s);
    std::vector<std::string> outWords;
    std::string word;
    while (iss >> word) {
        outWords.push_back(word);
    }

    // Split insideStr into words
    std::istringstream iss_in(insideStr);
    std::vector<std::string> inWords;
    while (iss_in >> word) {
        inWords.push_back(word);
    }

    // Find max word length
    int maxWordLength = 0;
    for (const auto &w : outWords) {
        if ((int)w.length() > maxWordLength) {
            maxWordLength = w.length();
        }
    }

    if (!insideStr.empty()) {
        std::cout << maxWordLength << " " << inWords.size() << std::endl;
    } else {
        std::cout << maxWordLength << " 0" << std::endl;
    }

    return 0;
}
